// Standardisasi & Filter Duplikasi Leads (WA vs Social DM)
const results = [];
const seen = new Set();

for (const item of $input.all()) {
  const d = item.json;

  // 1. Ekstrak & bersihkan nomor WA
  let rawPhone = d.primary_phone || (Array.isArray(d.phones) && d.phones[0]) || '';
  let phone = String(rawPhone).replace(/\D/g, '');
  if (phone.startsWith('0')) {
    phone = '62' + phone.slice(1);
  }

  // 2. Ekstrak & bersihkan username / profil sosmed
  let username = d.username || '';
  if (username && !username.startsWith('@') && !username.startsWith('http')) {
    username = '@' + username;
  }
  let profileUrl = d.url || (username.startsWith('@') ? `https://instagram.com/${username.replace('@','')}` : '');

  // Identifier unik (nomor WA atau link profil)
  const identifier = phone && phone.length >= 9 ? phone : (username || profileUrl);
  if (!identifier || seen.has(identifier)) {
    continue;
  }
  seen.add(identifier);

  const hasWa = Boolean(phone && phone.length >= 9);

  results.push({
    json: {
      has_wa: hasWa,
      Phone: hasWa ? phone : '',
      Nama_Bisnis: d.title || d.username || 'Kak',
      Username: username,
      Platform: d.platform || 'instagram',
      Kategori: d.category || 'Trading/Bisnis',
      Alamat_Lokasi: d.address || d.city || '',
      Profil_URL: profileUrl,
      Snippet_Bio: d.snippet || '',
      Source: d.source || 'Trendora Scraper',
      Status: hasWa ? 'QUEUED_FOR_WA' : 'READY_FOR_IG_DM',
      Last_Contacted: new Date().toISOString()
    }
  });
}

return results;

