let raw = $input.first().json.output || '';
raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(raw);
} catch (e) {
  const matchReply = raw.match(/"reply_message"\s*:\s*"([^"]+)"/);
  const matchSummary = raw.match(/"summary"\s*:\s*"([^"]+)"/);
  const matchStatus = raw.match(/"status"\s*:\s*"([^"]+)"/);

  parsed = {
    reply_message: matchReply ? matchReply[1] : raw,
    summary: matchSummary ? matchSummary[1] : 'Percakapan sedang berlangsung.',
    status: matchStatus ? matchStatus[1] : 'Interested'
  };
}

return [{
  json: {
    reply_message: parsed.reply_message || 'Terima kasih atas pesan Kakak! Ada yang bisa kami bantu seputar komunitas trading kami?',
    summary: parsed.summary || 'Prospek membalas chat WhatsApp.',
    status: parsed.status || 'Interested'
  }
}];

const now = new Date().getTime();
const eligibleLeads = [];

for (const item of $input.all()) {
  const d = item.json;
  const lastContact = d.Last_Contacted ? new Date(d.Last_Contacted).getTime() : 0;
  const hoursSince = (now - lastContact) / (1000 * 60 * 60);

  // Follow-up hanya untuk prospek WA yang belum closing dan sudah lewat >24 jam
  const eligibleStatus = ['INTRO_WA_SENT', 'FollowUp_Later', 'Interested'];
  if (d.Phone && d.Phone !== '-' && eligibleStatus.includes(d.Status) && hoursSince >= 24) {
    eligibleLeads.push({
      json: d
    });
  }
}

return eligibleLeads;

